// Build a department-specific onboarding checklist and a welcome email.
// Input (webhook JSON body): full_name, email, department, country, start_date, manager_email
const b = $json.body || $json;
const name = b.full_name || 'New Joiner';
const dept = b.department || 'General';
const country = b.country || '';
const start = b.start_date || '';

// Tasks every new hire gets.
const base = [
  'Create corporate email + SSO account',
  'Provision laptop and access badge',
  'Enroll in payroll and benefits',
  'Schedule Day-1 orientation',
  'Assign onboarding buddy'
];

// Extra tasks by department.
const byDept = {
  'Engineering': ['Grant Git/CI access', 'Add to on-call rotation (shadow)'],
  'Sales': ['Provision CRM seat', 'Assign territory and quota'],
  'Customer Support': ['Provision helpdesk seat', 'Enroll in product training'],
  'Finance': ['Grant ERP access (read-only)', 'Complete compliance training']
};

const tasks = base.concat(byDept[dept] || []);

const html = `<p>Hi ${name},</p>
<p>Welcome to the team! We are excited for your start date on <b>${start}</b> in <b>${dept}</b>${country ? ' (' + country + ')' : ''}.</p>
<p>Here is your onboarding checklist:</p>
<ul>${tasks.map(t => '<li>' + t + '</li>').join('')}</ul>
<p>Your manager will reach out shortly. See you soon!</p>
<p>— People Operations</p>`;

return [{ json: { name, email: b.email, department: dept, start_date: start, tasks, task_count: tasks.length, html } }];
